8	/// `export.status.get`'s own response `data` (`openapi.yaml:1495-1539`) —
9	/// decodes every field the contract declares, even [narrativeErrorCode]/
10	/// [downloadAvailable], which [toState] still never reads: the download
11	/// button's enabled/disabled treatment is driven entirely by which
12	/// [ExportJobState] `status` itself maps to (`ExportJobState.dataReady`/
13	/// `.done`), never by this flag — kept here so the DTO always mirrors the
14	/// full contract shape, not just today's consumer.
15	@JsonSerializable()
16	class ExportJobStatusDto {
17	  const ExportJobStatusDto({
18	    required this.jobId,
19	    required this.status,
20	    required this.narrativeStatus,
21	    required this.entryCount,
22	    required this.errorCode,
23	    required this.narrativeErrorCode,
24	    required this.downloadAvailable,
25	  });
26	
27	  final String jobId;
28	  final String status;
29	  final String narrativeStatus;
30	  final int? entryCount;
31	  final String? errorCode;
32	  final String? narrativeErrorCode;
33	  final bool downloadAvailable;
34	
35	  factory ExportJobStatusDto.fromJson(Map<String, dynamic> json) =>
36	      _$ExportJobStatusDtoFromJson(json);
37	
38	  Map<String, dynamic> toJson() => _$ExportJobStatusDtoToJson(this);
39	
40	  /// `docs/input/backend/export-screen-states.md`'s own status×
41	  /// narrativeStatus×downloadAvailable mapping table, implemented once
42	  /// here — `ExportRepositoryImpl.getStatus`'s own "thin pass-through"
43	  /// (Code Map) calls straight through to this method, with no mapping
44	  /// logic of its own.
45	  ///
46	  /// AD-3 ("reuse the existing `Failure.exportEmptyPeriod`... never add a
47	  /// new `Failure` subtype") is honored by going through the one shared
48	  /// [Failure.fromCode] for every `status: 'error'` response and then
49	  /// branching on the *subtype* it returns, rather than re-testing the
50	  /// literal `'EXPORT_EMPTY_PERIOD'` string a second time here — this
51	  /// stays correct even if a future taxonomy edit ever changed which code
52	  /// means "empty period", with no second place to update.
53	  ExportJobState toState() {
54	    switch (status) {
55	      case 'pending':
56	        return const ExportJobState.preparing();
57	      case 'processing':
58	        return const ExportJobState.generating();
59	      case 'data_ready':
60	        // spec-7-2 — its own state now: same progress-bar/text treatment
61	        // as `generating`, plus the raw-data button rendered already
62	        // enabled (`ExportJobState.dataReady`'s own doc).
63	        return const ExportJobState.dataReady();
64	      case 'done':
65	        return ExportJobState.done(
66	          narrativeStatus == 'done'
67	              ? ExportOutcome.narrativeReady
68	              : ExportOutcome.narrativeUnavailable,
69	        );
70	      case 'error':
71	        final failure = Failure.fromCode(
72	          errorCode ?? '',
73	          'Não foi possível gerar a exportação.',
74	        );
75	        return failure is ExportEmptyPeriod
76	            ? const ExportJobState.emptyPeriod()
77	            : ExportJobState.error(failure);
78	      default:
79	        // Forward-compatible: an unrecognized `status` (shouldn't happen —
80	        // the contract's own enum is closed) never crashes the poll loop
81	        // (RNF09) — surfaces as a terminal error instead.
82	        return ExportJobState.error(
83	          Failure.malformedResponse(message: 'Unknown export status: $status'),
84	        );
85	    }
86	  }
87	}
